// Validate the incoming payload before anything downstream touches it. A malformed request
// should fail here with a clear message, not three nodes later with a confusing one.
// (Code node mode: Run Once for All Items.)
const item = $input.first().json;
let body = item.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = undefined; }
}
if (!body || typeof body !== 'object') {
  throw new Error('Send a JSON body with header Content-Type: application/json, for example {"rawText": "...", "source": "n8n-test"}.');
}
const rawText = typeof body.rawText === 'string' ? body.rawText.trim() : '';
// Opsflow stores at most 40 characters of source and 4000 of text; fail here, not at the callback.
const source = (typeof body.source === 'string' && body.source.trim() ? body.source.trim() : 'n8n').slice(0, 40);

if (!rawText) {
  throw new Error('rawText is required and must be a non-empty string.');
}
if (rawText.length > 4000) {
  throw new Error('rawText is longer than the 4000 characters Opsflow accepts.');
}

return [{ json: { rawText, source } }];

