const cfg = $('Config: URL and Secret').first().json;
const baseUrl = String(cfg.baseUrl || '').trim().replace(/\/+$/, '');
const secret = String(cfg.callbackSecret || '').trim();
if (!/^https?:\/\/[^\s/]+$/.test(baseUrl)) {
  throw new Error('Config node: baseUrl must look like https://your-opsflow.vercel.app (no path, no trailing slash needed).');
}
if (!secret || secret.startsWith('PASTE')) {
  throw new Error("Config node: paste Opsflow's N8N_CALLBACK_SECRET into callbackSecret.");
}

const input = $input.first().json;
const rawText = input.rawText;
const source = input.source;
const body = JSON.stringify({ rawText });
const timestamp = new Date().toISOString();
const signature = hmacSha256Hex(secret, `${timestamp}.${body}`);

return [{ json: { rawText, source, url: `${baseUrl}/api/integrations/classify`, body, timestamp, signature } }];

// Merge the classify response with the original rawText/source, which the HTTP Request
// node's output doesn't carry forward on its own.
// (Code node mode: Run Once for All Items.)
const c = $input.first().json;
const original = $('Sign Classify Request').first().json;

if (typeof c.confidence !== 'number' || typeof c.classification !== 'string') {
  throw new Error('Unexpected response from Opsflow classify: ' + JSON.stringify(c).slice(0, 300));
}

return [{
  json: {
    rawText: original.rawText,
    source: original.source,
    classification: c.classification,
    priority: c.priority,
    summary: c.summary,
    confidence: c.confidence,
    sourceSnippet: c.sourceSnippet,
  },
}];

